// Selected official MultiFontTextMaterial; generated by prepare_activity_battle_page_support.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
namespace Zjcs.Official.ActivityBattleUI
{
using Object = UnityEngine.Object;
using TMPro;
using UnityEngine;

[RequireComponent(typeof(WorldMultiLanguageText), typeof(TMP_Text))]
public class MultiFontTextMaterial : MonoBehaviour
{
	public string MaterialClassName;

	private WorldMultiLanguageText mMultiLanguageText;

	private TMP_Text mTxt;

	private IProfessionAssetOperation<Material> mAssetOperationHandle;

	private const string kMaterialFullNameFormat = "{0} - {1}.g";

	private IFontAssetFontService FontAssetFontService { get; set; }

	private IProfessionImageResourceLoader ResourceLoader { get; set; }

	public void Configure(IFontAssetFontService fonts, IProfessionImageResourceLoader resources)
	{ FontAssetFontService = fonts; ResourceLoader = resources; }

	private void Awake()
	{
		mMultiLanguageText = ((Component)this).GetComponent<WorldMultiLanguageText>();
		mTxt = ((Component)this).GetComponent<TMP_Text>();
	}

	private void OnEnable()
	{
		mMultiLanguageText.OnFontChanged += OnTxtFontChanged;
		EnsureFontMaterial();
	}

	private void OnDisable()
	{
		mMultiLanguageText.OnFontChanged -= OnTxtFontChanged;
	}

	private void OnTxtFontChanged()
	{
		EnsureFontMaterial();
	}

	private void EnsureFontMaterial()
	{
		string sourceFontFileName = FontAssetFontService.GetSourceFontFileName(mTxt.font);
		string text = $"{sourceFontFileName} - {MaterialClassName}.g";
		mAssetOperationHandle?.Dispose();
		mAssetOperationHandle = ResourceLoader.LoadAsset<Material>(text);
		if ((Object)(object)mAssetOperationHandle.Result == (Object)null)
		{
			Debug.LogError("未能找到目标字体材质:" + text, this);
			mAssetOperationHandle.Dispose();
			mAssetOperationHandle = null;
		}
		else
		{
			mTxt.fontMaterial = mAssetOperationHandle.Result;
		}
	}

	private void OnDestroy()
	{
		mAssetOperationHandle?.Dispose();
		mAssetOperationHandle = null;
	}

	[ContextMenu("刷新字体材质")]
	public void RefreshFontMaterial()
	{
		EnsureFontMaterial();
	}
}

}
